def normalize_path(path: str) -> str:
    """
    Normalize a Unix-style POSIX path string by resolving '.' and '..'
    components and collapsing redundant separators.
    """
    if not path:
        return "."

    is_absolute = path.startswith("/")

    # Split on '/' and filter out empty parts and '.' components
    parts = path.split("/")

    stack = []
    for part in parts:
        if part == "" or part == ".":
            # Skip empty parts (from consecutive slashes or leading/trailing slash)
            continue
        elif part == "..":
            if is_absolute:
                # Can't go above root
                if stack:
                    stack.pop()
            else:
                # Relative path: if stack is non-empty and top is not '..', pop
                if stack and stack[-1] != "..":
                    stack.pop()
                else:
                    # Preserve leading '..' components
                    stack.append("..")
        else:
            stack.append(part)

    if is_absolute:
        return "/" + "/".join(stack)
    else:
        result = "/".join(stack)
        return result if result else "."
